import React, { useState } from 'react';
import '../styles/ReviewsSection.css';

const ReviewsSection = () => {
    const [showAllReviews, setShowAllReviews] = useState(false);
    
    const reviews = [
        {
            id: 1,
            text: 'Дуже задоволена покупкою! Меблі якісні, стильні та зручні. Доставка була швидкою, а монтаж професійним. Рекомендую цей магазин усім, хто цінує комфорт та дизайн.',
            rating: 5,
            author: 'Олена Коваль',
            profession: 'Дизайнер інтер\'єрів',
            avatar: `${process.env.PUBLIC_URL}/imgg/Ellipse 2 (1).png`
        },
        {
            id: 2,
            text: 'Купували кухонний гарнітур. Якість чудова, все підійшло за розміром. Єдиний недолік - трохи довго чекали доставки, але результат того вартий.',
            rating: 4,
            author: 'Ігор Петренко',
            profession: 'Архітектор',
            avatar: `${process.env.PUBLIC_URL}/imgg/Ellipse 2 (2).png`
        },
        {
            id: 3,
            text: 'Замовляли диван та крісла. Дуже задоволені! Меблі зручні, якісні, виглядають стильно. Консультант допоміг підібрати оптимальний варіант для нашої вітальні.',
            rating: 5,
            author: 'Наталія Сидоренко',
            profession: 'Менеджер',
            avatar: `${process.env.PUBLIC_URL}/imgg/Ellipse 2 (3).png`
        },
        {
            id: 4,
            text: 'Чудовий сервіс та якість! Замовляли спальню, все прийшло вчасно, без пошкоджень. Збирали самостійно, інструкція була зрозумілою. Дякую!',
            rating: 5,
            author: 'Андрій Мельник',
            profession: 'Підприємець',
            avatar: `${process.env.PUBLIC_URL}/imgg/Ellipse 2.png`
        }
    ];

    const displayedReviews = showAllReviews ? reviews : reviews.slice(0, 2);
    
    const toggleReviews = (e) => {
        e.preventDefault();
        setShowAllReviews(!showAllReviews);
    };

    return (
        <section className="reviews-section">
            <div className="reviews-header">
                <h2>Відгуки кліентів</h2>
            </div>
            <div className="reviews-grid">
                {displayedReviews.map(review => (
                    <div key={review.id} className="review-card">
                        <div className="review-rating">
                            <div className="stars">{'★'.repeat(review.rating)}{'☆'.repeat(5 - review.rating)}</div>
                        </div>
                        <div className="review-text">{review.text}</div>
                        <div className="review-author">
                            <img src={review.avatar} alt={review.author} className="review-author-avatar" />
                            <div className="review-author-info">
                                <div className="review-author-name">{review.author}</div>
                                <div className="review-author-profession">{review.profession}</div>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
            <a href="#" className="reviews-btn" onClick={toggleReviews}>
                {showAllReviews ? 'Показати менше' : 'Переглянути всі відгуки'}
            </a>
        </section>
    );
};

export default ReviewsSection;
